css:
.platform-radius-4{border-radius:0.2777778cqi}
.platform-radius-6{border-radius:0.4166667cqi}
.platform-radius-8{border-radius:0.5555556cqi}
.platform-person-content{display:flex;flex-direction:column;width:100%;height:100%;padding:1.1111111cqi 1.6666667cqi 2.2222222cqi;color:#4b4b4b;font-size:0.9722222cqi;line-height:1.3888889cqi;min-width:0}
.platform-person-header{display:flex;flex-direction:column;margin-top:1.9444444cqi;flex-shrink:0}
.platform-person-title{display:flex;align-items:center;column-gap:0.5555556cqi;font-size:1.3888889cqi;line-height:2.0833333cqi;font-weight:600;color:#121212}
.platform-person-type{background-color:#fffbea;color:#bf4a00;font-size:0.9027778cqi;line-height:1.2500000cqi;font-weight:500;padding:0.0694444cqi 0.5555556cqi}
.platform-person-state{background-color:#edfcf2;color:#087443;font-size:0.9027778cqi;line-height:1.2500000cqi;font-weight:500;padding:0.0694444cqi 0.5555556cqi}
.platform-person-id{display:flex;align-items:center;column-gap:0.4166667cqi;margin-top:0.2777778cqi}
.platform-person-copy{display:flex;width:0.9722222cqi;height:0.9722222cqi}
.platform-person-tabs{display:flex;column-gap:1.1111111cqi;border-bottom:0.0694444cqi solid #efefef;margin-top:1.6666667cqi}
.platform-person-tab{padding:0.0694444cqi 0.2777778cqi 0.7638889cqi;font-weight:600;color:#5d5d5d;white-space:nowrap}
.platform-person-tab.is-active{border-bottom:0.1388889cqi solid #121212;color:#121212}
.platform-person-body{display:grid;grid-template-columns:minmax(0,792fr) minmax(0,320fr);grid-template-rows:auto;column-gap:2.2222222cqi;margin-top:1.6666667cqi;width:100%}
.platform-person-main{display:flex;flex-direction:column;row-gap:1.6666667cqi;min-width:0}
.platform-person-details{display:flex;flex-direction:column;row-gap:0.8333333cqi}
.platform-person-section-heading{display:flex;align-items:center;justify-content:space-between;height:2.2222222cqi;font-size:1.1111111cqi;line-height:1.6666667cqi;font-weight:600;color:#121212}
.platform-person-action{display:flex;align-items:center;justify-content:center;width:2.2222222cqi;height:2.2222222cqi;flex-shrink:0;border:0.0694444cqi solid #d1d1d1;background-color:#fff;box-shadow:0 0.0694444cqi 0.1388889cqi #1212120d}
.platform-person-fields{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:auto;column-gap:1.1111111cqi}
.platform-person-field-column{display:flex;flex-direction:column;row-gap:0.5555556cqi}
.platform-person-field{display:flex;column-gap:0.5555556cqi;align-items:flex-start;white-space:nowrap}
.platform-person-label{font-weight:500}
.platform-person-locales{display:flex;flex-direction:column;row-gap:0.8333333cqi;margin-top:0.2777778cqi;margin-bottom:0.2777778cqi}
.platform-person-locales-heading{font-weight:600;color:#121212}
.platform-person-sections{display:flex;flex-direction:column;row-gap:0.8333333cqi}
.platform-collapsible-heading{display:flex;align-items:center;column-gap:0.5555556cqi;height:2.5000000cqi;width:100%;flex-shrink:0;padding:0.5555556cqi 1.1111111cqi 0.5555556cqi 0.5555556cqi;border:0.0694444cqi solid #efefef;background-color:#f9f9f9;color:#121212;font-weight:500}
.platform-collapsible-count{border:0.0694444cqi solid #e7e7e7;padding-left:0.4166667cqi;padding-right:0.4166667cqi;font-size:0.8333333cqi;line-height:1.1111111cqi;color:#4b4b4b}
.platform-person-empty-panel{display:flex;flex-direction:column;row-gap:1.1111111cqi;width:100%}
.platform-person-empty-state{display:flex;align-items:center;justify-content:center;width:100%;height:4.7222222cqi;border:0.0694444cqi dashed #d1d1d1;padding:1.6666667cqi 5.5555556cqi;color:#888;text-align:center;white-space:nowrap}
